'use strict';
const modules={
 pessoas:{title:'Pessoas & operação',symbol:'✳',items:[['Talent','Recrutamento e seleção'],['People','Admissão e jornada profissional'],['Time','Ponto e escalas'],['Payroll','Folha e departamento pessoal']],description:'A visão: conectar a contratação, a rotina da equipe e as informações de gestão em uma base consistente.'},
 desenvolvimento:{title:'Desenvolvimento & cultura',symbol:'↗',items:[['Academy','Educação e trilhas de carreira'],['Performance','Metas e desenvolvimento'],['Retention','Escuta e planos de retenção'],['Connect','Comunicação e cultura']],description:'A visão: transformar aprendizagem, feedback e comunicação em uma jornada contínua de crescimento.'},
 recompensas:{title:'Reconhecimento & recompensas',symbol:'✦',items:[['Rewards','Mr. Coin integrado à jornada'],['Campanhas','Metas individuais e coletivas'],['Carteira COIN$','Conquistas e movimentações'],['Governança','Orçamento, regras e aprovação']],description:'A visão: reconhecer contribuições verificáveis, com critérios claros e acompanhamento do investimento.'},
 inteligencia:{title:'Inteligência & resultados',symbol:'⌘',items:[['Intelligence','Agentes de IA especializados'],['Command','Visão executiva e indicadores'],['Compliance','Obrigações e evidências'],['Ações conectadas','Analisar, aprovar e acompanhar']],description:'A visão: transformar dados em recomendações explicáveis e processos autorizados, com revisão humana.'}
};
const panel=document.querySelector('#module-panel');
const tabs=[...document.querySelectorAll('[data-module]')];
function selectModule(tab){const data=modules[tab.dataset.module];tabs.forEach(item=>{const selected=item===tab;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1;});panel.setAttribute('aria-labelledby',tab.id);panel.innerHTML=`<div class="panel-top"><span>${data.title}</span><span class="panel-status">VISÃO DO PRODUTO</span></div><div class="panel-illustration" aria-hidden="true"><span class="profile-bubble">♙</span><span class="connection"></span><span class="connection-center">${data.symbol}</span><span class="connection"></span><span class="profile-bubble">♙</span></div><div class="module-cards">${data.items.map(([name,detail])=>`<div class="module-card"><strong>${name}</strong>${detail}</div>`).join('')}</div><p class="panel-description">${data.description}</p>`;}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectModule(tab));tab.addEventListener('keydown',event=>{let next=index;if(event.key==='ArrowDown'||event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowUp'||event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();tabs[next].focus();selectModule(tabs[next]);});});selectModule(tabs[0]);
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#navigation');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');menu.textContent='☰';}menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',expanded);menu.setAttribute('aria-expanded',String(expanded));menu.setAttribute('aria-label',expanded?'Fechar menu':'Abrir menu');menu.textContent=expanded?'×':'☰';});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
document.querySelectorAll('[data-sector]').forEach(link=>link.addEventListener('click',()=>{document.querySelector('#segmento').value=link.dataset.sector;}));
const form=document.querySelector('#contact-form');form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const message=`Olá, Ricardo! Quero conhecer a Pipou para minha empresa.\n\nNome: ${data.get('nome').trim()}\nE-mail: ${data.get('email').trim()}\nEmpresa: ${data.get('empresa').trim()}\nSegmento: ${data.get('segmento')}\nEquipe: ${data.get('equipe')}\n\nPodemos conversar sobre as soluções disponíveis?`;const url='https://wa.me/5513997770666?text='+encodeURIComponent(message);const fallback=document.querySelector('#whatsapp-fallback');fallback.href=url;fallback.hidden=false;document.querySelector('#form-status').textContent='Mensagem preparada. Revise os dados e confirme o envio no WhatsApp.';window.open(url,'_blank','noopener,noreferrer');});
const privacy=document.querySelector('#privacy');document.querySelector('.privacy-trigger').addEventListener('click',()=>privacy.showModal());document.querySelector('.close-dialog').addEventListener('click',()=>privacy.close());privacy.addEventListener('click',event=>{if(event.target===privacy){const rect=privacy.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)privacy.close();}});document.querySelector('#year').textContent=new Date().getFullYear();

const appScreens=[{"id": "inicio", "tab": "Início", "eyebrow": "TUDO COMEÇA AQUI", "title": "O dia da sua equipe, em uma tela.", "description": "Uma visão pessoal da rotina: identificação do colaborador, saldo de coins, registro de entrada, banco de horas e acesso às férias.", "items": ["Resumo da jornada e acesso ao ponto", "Saldo de coins e posição no ranking", "Atalhos para banco de horas e férias"], "alt": "Tela inicial da Pipou com saudação, coins, registro de entrada, banco de horas e férias."}, {"id": "ponto", "tab": "Ponto", "eyebrow": "JORNADA COM CLAREZA", "title": "A rotina de trabalho, mais fácil de acompanhar.", "description": "O colaborador encontra o registro de entrada, as marcações do dia e o histórico da jornada no mesmo lugar.", "items": ["Acesso ao registro de entrada", "Consulta das marcações do dia", "Histórico com registros e dias de folga"], "alt": "Tela de ponto do app Pipou, com botão Registrar entrada, pontos de hoje e histórico da jornada."}, {"id": "holerites", "tab": "Holerites", "eyebrow": "INFORMAÇÃO NA MÃO", "title": "Mais transparência sobre cada recebimento.", "description": "A tela financeira organiza a consulta mensal do holerite, com os componentes da remuneração, descontos e opção de exportação.", "items": ["Consulta de salários, adicionais e descontos", "Detalhamento do valor líquido por competência", "Opção de exportar o demonstrativo"], "alt": "Tela demonstrativa de holerites da Pipou com rubricas, descontos, valor líquido e botão Exportar."}, {"id": "gorjetas", "tab": "Gorjetas", "eyebrow": "CADA DETALHE CONTA", "title": "Gorjetas com informações que fazem sentido.", "description": "Uma consulta por mês que reúne valores, pontuação, valor do ponto e dias trabalhados para facilitar a compreensão do rateio.", "items": ["Valores bruto e líquido por período", "Pontuação e valor do ponto em destaque", "Dias trabalhados apresentados na mesma tela"], "alt": "Tela de gorjetas com valores mensais, pontuação, valor do ponto e dias trabalhados."}, {"id": "banco-de-horas", "tab": "Banco de horas", "eyebrow": "TEMPO BEM ACOMPANHADO", "title": "O saldo de horas, explicado.", "description": "Saldo anterior, horas extras e débitos aparecem separados. O colaborador acompanha como o novo saldo é composto em cada mês.", "items": ["Saldo anterior e novo saldo mensal", "Separação entre créditos e débitos de horas", "Histórico organizado por competência"], "alt": "Tela Banco de Horas da Pipou com saldo anterior, horas extras, débitos e novo saldo mensal."}, {"id": "theo", "tab": "Theo", "eyebrow": "UMA CONVERSA QUE AJUDA", "title": "Conheça o Theo, o assistente da equipe.", "description": "Um espaço de conversa para dúvidas da rotina. A experiência apresentada prevê orientação sobre ponto, banco de horas, férias e holerites.", "items": ["Atendimento em uma interface de conversa", "Orientação sobre informações do dia a dia", "Acesso direto na navegação do aplicativo"], "alt": "Tela de conversa com Theo, assistente apresentado no aplicativo Pipou."}, {"id": "reconhecimento", "tab": "Reconhecimento", "eyebrow": "QUEM FAZ ACONTECER, APARECE", "title": "Conquistas que ganham visibilidade.", "description": "O ranking da equipe apresenta posições, coins e mensagens de reconhecimento. O perfil mantém as informações do colaborador e o acesso à sua conta.", "items": ["Ranking da equipe e saldo de coins", "Destaques e mensagens de reconhecimento", "Perfil do colaborador e sua função"], "alt": "Ranking da equipe no app Pipou, com posições, coins, reconhecimento e perfil do colaborador."}, {"id": "mais", "tab": "Mais recursos", "eyebrow": "UM ESPAÇO PARA CADA NECESSIDADE", "title": "Os outros caminhos da jornada, reunidos.", "description": "A área Mais organiza os atalhos para documentos, férias, desenvolvimento, clima e campanhas, além da preferência de tema do aplicativo.", "items": ["Documentos e férias em atalhos próprios", "Acesso a desenvolvimento, clima e campanhas", "Preferência de modo noite"], "alt": "Área Mais do aplicativo com atalhos para Documentos, Férias, Desenvolvimento, Clima, Campanhas e Modo noite."}];

const appTabs=[...document.querySelectorAll('[data-screen]')];
const appPanel=document.querySelector('#app-panel');
const appImage=document.querySelector('#app-image');
const appPreview=document.querySelector('#app-preview');
let appScreenIndex=0;
function selectAppScreen(index,focusTab=false){
 appScreenIndex=(index+appScreens.length)%appScreens.length;
 const screen=appScreens[appScreenIndex];
 appTabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===appScreenIndex));tab.tabIndex=i===appScreenIndex?0:-1;});
 appPanel.setAttribute('aria-labelledby',appTabs[appScreenIndex].id);
 document.querySelector('#app-eyebrow').textContent=screen.eyebrow;
 document.querySelector('#app-title').textContent=screen.title;
 document.querySelector('#app-description').textContent=screen.description;
 const list=document.querySelector('#app-features');list.replaceChildren(...screen.items.map(text=>{const item=document.createElement('li');item.textContent=text;return item;}));
 appImage.src='assets/app/'+screen.id+'.jpeg';appImage.alt=screen.alt;
 document.querySelector('#app-counter').textContent=String(appScreenIndex+1).padStart(2,'0')+' / 08 · '+screen.tab;
 if(focusTab){appTabs[appScreenIndex].focus();appTabs[appScreenIndex].scrollIntoView({block:'nearest',inline:'nearest'});}
}
appTabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectAppScreen(index));tab.addEventListener('keydown',event=>{let next=index;if(event.key==='ArrowRight')next++;else if(event.key==='ArrowLeft')next--;else if(event.key==='Home')next=0;else if(event.key==='End')next=appScreens.length-1;else return;event.preventDefault();selectAppScreen(next,true);});});
document.querySelector('#app-previous').addEventListener('click',()=>selectAppScreen(appScreenIndex-1));
document.querySelector('#app-next').addEventListener('click',()=>selectAppScreen(appScreenIndex+1));
function openAppPreview(){const screen=appScreens[appScreenIndex];const img=document.querySelector('#app-preview-image');img.src='assets/app/'+screen.id+'.jpeg';img.alt=screen.alt;document.querySelector('#app-preview-title').textContent='Pipou · '+screen.tab;appPreview.showModal();}
document.querySelector('.app-screen-button').addEventListener('click',openAppPreview);
document.querySelector('.app-enlarge').addEventListener('click',openAppPreview);
document.querySelector('.close-app-preview').addEventListener('click',()=>appPreview.close());
appPreview.addEventListener('click',event=>{if(event.target===appPreview){const rect=appPreview.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)appPreview.close();}});
